mapper.update:
update Pc_Award_Ticket set Pay_Id=null
where At_Id in

    #{atId}

update Pc_Award_Ticket set Pay_Id=#{payId}
where At_Id in

    #{atId}

mapper.select:
select
con.Con_Name as conName,
con.Con_Code as conCode,

c1.C_Name_History as atCNameHistory,
c1.C_Name as atCName,
c1.C_Abbreviation as atCAbbName,
pay.Pay_Code as payCode,
pay.Pay_Type as payType,
pay.Pay_Type_Detailed as payTypeDetailed,
pay.Pay_Create_Time as payCreateTime,
pay.Pay_State as payState,
mn.*
from Pc_Award_Ticket mn
left join Con_Contract con on con.Con_Id=mn.Con_Id

left join SYS_Company c1 on c1.C_Id=mn.At_C_Id
left join Con_Pay pay on pay.Pay_Id=mn.Pay_Id
${params.authSql}

    and mn.Te_Id = #{params.teId}


    and mn.P_Id=#{params.pId}


    and mn.At_Type=#{params.atType}


    and mn.At_C_Id=#{params.atCId}


    and mn.Pay_Id=#{params.payId}


    and mn.At_State=#{params.atState}


    and mn.Con_Id=#{params.conId}


    and mn.At_State=7 and (
     mn.Pay_Id is null or (select cp0.Pay_State from Con_Pay cp0 where cp0.Pay_Id=mn.Pay_Id)=3
     
         or mn.Pay_Id=#{params.payId}
     
    )


    
        
            and likeCname(#{params.atCName},c1.C_Id)=true
        
        
            and c1.C_Name like concat('%',#{params.atCName},'%')
        
    


    and mn.At_Code like concat('%',#{params.atCode},'%')


    
        
            and likePname(#{params.pName},pro.P_Id)=true
        
        
            and pro.P_Name like concat('%',#{params.pName},'%')
        
    


    and con.Con_Name like concat('%',#{params.conName},'%')


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.At_Create_Time desc
